package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import thaumcraft.api.aspects.Aspect;
final class KamiToolsAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT KAMI tools: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){
  String[] keys={"ICHOR_PICK","ICHOR_SHOVEL","ICHOR_AXE","ICHOR_SWORD"};var items=java.util.List.of(KamiTools.PICK.get(),KamiTools.SHOVEL.get(),KamiTools.AXE.get(),KamiTools.SWORD.get());Aspect[] aspects={Aspect.FIRE,Aspect.EARTH,Aspect.WATER,Aspect.AIR};String[] patterns={"III R  R "," I  R  R ","II IR  R "," I  I  R "};
  for(int i=0;i<4;i++){final String key=keys[i];var recipe=dev.eugheist.tc4modern.ArcaneRecipes.entries().stream().filter(r->r.key().equals(key)).findFirst().orElseThrow();var grid=new java.util.ArrayList<ItemStack>();for(char c:patterns[i].toCharArray())grid.add(c==' '?ItemStack.EMPTY:new ItemStack(c=='I'?KamiResources.item(KamiResources.Kind.ICHORIUM):dev.eugheist.tc4modern.WandParts.RODS.get("silverwood").get()));check(dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of("ICHOR_TOOLS"))==recipe&&dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of())==null,"native recipe/lock "+key);check(recipe.cost().size()==1&&recipe.cost().getAmount(aspects[i])==75&&recipe.output().is(items.get(i)),"original cost/output "+key);var stack=new ItemStack(items.get(i));double damage=stack.get(net.minecraft.core.component.DataComponents.ATTRIBUTE_MODIFIERS).modifiers().stream().filter(e->e.attribute().equals(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)).mapToDouble(e->e.modifier().amount()).sum();check(damage==new int[]{7,6,8,9}[i],"original 1.7.10 attack attribute "+key);check(stack.hasFoil()&&stack.getRarity()==Rarity.EPIC&&stack.getMaxStackSize()==1&&!stack.isDamageableItem()&&items.get(i).getEnchantmentValue()==25,"original foil/rarity/unbreakable/enchantability "+key);stack.hurtAndBreak(10000,server.overworld(),null,item->{});check(stack.getCount()==1&&stack.getDamageValue()==0,"native durability immunity "+key);var restored=ItemStack.parseOptional(server.registryAccess(),(net.minecraft.nbt.CompoundTag)stack.save(server.registryAccess()));check(!restored.isDamageableItem()&&restored.hasFoil(),"native persistence "+key);}
  var pick=new ItemStack(KamiTools.PICK.get());check(pick.isCorrectToolForDrops(Blocks.OBSIDIAN.defaultBlockState())&&pick.isCorrectToolForDrops(Blocks.ANCIENT_DEBRIS.defaultBlockState())&&pick.getDestroySpeed(Blocks.STONE.defaultBlockState())==10,"tier4 pick mining");check(new ItemStack(KamiTools.AXE.get()).getDestroySpeed(Blocks.OAK_LOG.defaultBlockState())==10&&new ItemStack(KamiTools.SHOVEL.get()).getDestroySpeed(Blocks.DIRT.defaultBlockState())==10,"axe/shovel mining speed");var research=thaumcraft.api.research.ResearchCategories.getResearch("ICHOR_TOOLS");check(research instanceof KamiResearch&&research.getPages().length==5&&java.util.Arrays.equals(research.parents,new String[]{"ICHORIUM"})&&java.util.Arrays.asList(research.parentsHidden).contains("ROD_ICHORCLOTH")&&dev.eugheist.tc4modern.ResearchWarp.amount("ICHOR_TOOLS")==2,"research progression/pages/warp");for(int i=0;i<4;i++)check(research.getPages()[i+1].recipeKey.equals(keys[i]),"original page order");
  System.out.println("TT KAMI TOOLS AUDIT: ALL PASS (four native original recipes/costs/locks,unbreakable durability/persistence,enchantability,tier4 mining/speed,research/pages/warp)");
 }
}
